sys_script_include.script:
var SGCeburuConnectionUtil = Class.create();
SGCeburuConnectionUtil.prototype = {
    initialize: function() {
        this.encr = new global.Encrypter();
        this.IntegrationUtil = new x_cesy_service_gr.SGCeburuIntegrationUtil();
        this.PDIOauth = {
            "username": gs.getProperty("x_cesy_service_gr.pdi.username"),
            "password": gs.getProperty("x_cesy_service_gr.pdi.password"),
            "client_id": gs.getProperty("x_cesy_service_gr.pdi.client.id"),
            "client_secret": gs.getProperty("x_cesy_service_gr.pdi.client.secret"),
            "endpoint": gs.getProperty("x_cesy_service_gr.pdi.endpoint")
        };
    },

	getDemoToken: function(){
		var DemoToken = new GlideRecord("oauth_credential");
        DemoToken.addQuery("peer.name", "Demo");
        DemoToken.addQuery("type", "access_token");
        DemoToken.query();

		if(DemoToken.next()){
			return DemoToken.token_received;
		}
	},

    getPDIToken: function() {
		return this.getPDIAccessToken();
    },

    getPDIAccessToken: function() {
        var PDIToken = new GlideRecord("oauth_credential");
        PDIToken.addQuery("peer.name", "PDI");
        PDIToken.addQuery("type", "access_token");
        PDIToken.query();

        if (PDIToken.next()) {
            return PDIToken.token_received;
        } else {
			return this.setPDIAccessToken();
        }
    },

    setPDIAccessToken: function() {
        var refreshToken = this.encr.decrypt(this.getPDIRefreshToken());
		var clientSecret = this.encr.decrypt(this.PDIOauth.client_secret);

        var restMessage = this.IntegrationUtil.createRESTMessage(
            this.PDIOauth.endpoint,
            "post", {
                "Content-Type": "application/x-www-form-urlencoded"
            },
            "grant_type=refresh_token&client_id=" + this.PDIOauth.client_id + "&client_secret=" + clientSecret + "&refresh_token=" + refreshToken
        );
        var messageBody = JSON.parse(restMessage.getBody());

        // Store the retrieved token and return it
        var PDIToken = new GlideRecord("oauth_credential");
        PDIToken.initialize();
        PDIToken.peer.setDisplayValue("PDI");
        PDIToken.type = "access_token";
        PDIToken.token_received = this.encr.encrypt(messageBody.access_token);
        var expiresIn = new GlideDateTime();
		var ms = expiresIn.getNumericValue();
		expiresIn.setNumericValue(ms + (messageBody.expires_in * 1000));
        PDIToken.expires = expiresIn;
        var token_sys_id = PDIToken.insert();
        return this.encr.encrypt(messageBody.access_token);
    },

    getPDIRefreshToken: function() {
        var PDIToken = new GlideRecord("oauth_credential");
        PDIToken.addQuery("peer.name", "PDI");
        PDIToken.addQuery("type", "refresh_token");
        PDIToken.query();

        if (PDIToken.next()) {
            return PDIToken.token_received;
        } else {
            return this.setPDIRefreshToken();
        }
    },

    setPDIRefreshToken: function() {
		var clientSecret = this.encr.decrypt(this.PDIOauth.client_secret);
		var password = this.encr.decrypt(this.PDIOauth.password);

        var restMessage = this.IntegrationUtil.createRESTMessage(
            this.PDIOauth.endpoint,
            "post", {
                "Content-Type": "application/x-www-form-urlencoded"
            },
            "grant_type=password&username=" + this.PDIOauth.username + "&password=" + password + "&client_id=" + this.PDIOauth.client_id + "&client_secret=" + clientSecret
        );
        var messageBody = JSON.parse(restMessage.getBody());

        // Store the retrieved token and return it
        var PDIToken = new GlideRecord("oauth_credential");
        PDIToken.initialize();
        PDIToken.peer.setDisplayValue("PDI");
        PDIToken.type = "refresh_token";
        PDIToken.token_received = this.encr.encrypt(messageBody.refresh_token);
        var expiresIn = new GlideDateTime();
		var ms = expiresIn.getNumericValue();
		expiresIn.setNumericValue(ms + (8640000 * 1000));
        PDIToken.expires = expiresIn;
        var token_sys_id = PDIToken.insert();
        return this.encr.encrypt(messageBody.refresh_token);
    },

    testConnection: function(gr) {
        gr.status = "Pending";
        gr.message = "";
        gr.suggestion = "";
        gr.status_code = "";
        gr.update();
        var connectionAlias = new GlideRecordSecure('sys_alias');

        try {
            var inputs = {};
            if (connectionAlias.get("id", "x_cesy_service_gr.SG_Ceburu_Connection_Alias")) {
                inputs["credentials_alias"] = connectionAlias;
            }
            var result = sn_fd.FlowAPI.getRunner().action('x_cesy_service_gr.sgceburu_import_organizations').inForeground().withInputs(inputs).run();
            var outputs = result.getOutputs();
            // Get Outputs:
            // Note: outputs can only be retrieved when executing synchronously.
            var errorcode = outputs['errorcode']; // String
            var errormessage = outputs['errormessage']; // String
            var responsebody = outputs['responsebody']; // String
            var responseheaders = outputs['responseheaders']; // String
            var statuscode = outputs['statuscode']; // String
            gr.status_code = statuscode;

            var helpfulErrorMessage;
            if (!gs.nil(responsebody)) {
                try {
                    var responseBodyJson = JSON.parse(responsebody.replace("\\", ""));
                    if (gs.nil(responsebody) && !gs.nil(responseBodyJson.error) && !gs.nil(responseBodyJson.error.message)) {
                        helpfulErrorMessage = responseBodyJson.error.message;
                    }
                } catch (ex) {}
            }
            if (gs.nil(helpfulErrorMessage)) {
                helpfulErrorMessage = errormessage;
            }

            if (statuscode == "200" || gs.nil(errormessage)) {
                gs.addInfoMessage(gs.getMessage("Success"));
                gr.status = "Success";
                gr.message = "";
                gr.suggestion = "";
            } else if (statuscode == "401") {
                gs.addInfoMessage(gs.getMessage("Error: {0}", errormessage));
                gr.status = "Error";
                gr.message = helpfulErrorMessage;
                gr.suggestion = gs.getMessage("Status code: {0}. Invalid HCP Ceburu or Ceburu Enterprise API token.", statuscode);
            } else if (statuscode == "403") {
                gs.addInfoMessage(gs.getMessage("Error: {0}", errormessage));
                gr.status = "Error";
                gr.message = helpfulErrorMessage;
                gr.suggestion = gs.getMessage("Status code: {0}. ndicates an error has occured. Further debugging is required.", statuscode);
            } else if (statuscode == "404") {
                gs.addInfoMessage(gs.getMessage("Error: {0}", errormessage));
                gr.status = "Error";
                gr.message = helpfulErrorMessage;
                gr.suggestion = gs.getMessage("Status code: {0}. Indicates an error has occured. Further debugging is required.", statuscode);
            } else {
                gs.addInfoMessage(gs.getMessage("Error: {0}", errormessage));
                gr.status = "Error";
                gr.message = helpfulErrorMessage;
                gr.suggestion = gs.getMessage("Status code: {0}. Indicates an error has occured. Further debugging is required.", statuscode);
            }
            gr.update();

        } catch (ex) {
            var message = ex.getMessage();
            gs.addErrorMessage(gs.getMessage("Error: {0}", message));
            gs.error(message);
            gr.status = "Exception raised by the test script";
            gr.message = message;
            gr.suggestion = gs.getMessage("Indicates an error has occured. Further debugging is required.");
            gr.update();
        }

    },

    type: 'SGCeburuConnectionUtil'
};
